using System.Windows; using System.Windows.Controls; using Microsoft.EntityFrameworkCore;
namespace SalesManagement_SysDev;

public abstract class ListWindow : Window
{
 protected DataGrid Grid=new(); protected TextBox Search=new(); protected SalesManagementContext Db=new(); protected ListWindow(string title){Title=title;Width=1050;Height=650;FontFamily=new System.Windows.Media.FontFamily("Meiryo");var p=new DockPanel();var top=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(8)};top.Children.Add(new TextBlock{Text="検索",VerticalAlignment=VerticalAlignment.Center});top.Children.Add(Search);Search.Width=220;var b=new Button{Content="再読込",Margin=new Thickness(8,0,0,0)};b.Click+=(s,e)=>Load();top.Children.Add(b);DockPanel.SetDock(top,Dock.Top);p.Children.Add(top);Grid.AutoGenerateColumns=true;Grid.IsReadOnly=true;p.Children.Add(Grid);Content=p;}
 protected abstract void Load(); protected void ShowError(Exception ex)=>MessageBox.Show("処理に失敗しました。\n"+ex.Message,"エラー",MessageBoxButton.OK,MessageBoxImage.Error);
 protected void Display<T>(IEnumerable<T> rows){Grid.ItemsSource=rows.ToList();}
}
public sealed class F_Client:ListWindow{public F_Client():base("顧客管理"){Load();}protected override void Load(){try{Display(Db.MClients.Include(x=>x.So).Where(x=>x.ClFlag==0).Select(x=>new{ID=x.ClId,顧客名=x.ClName,営業所=x.So.SoName,電話=x.ClPhone}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Product:ListWindow{public F_Product():base("商品管理"){Load();}protected override void Load(){try{Display(Db.MProducts.Include(x=>x.Ma).Include(x=>x.Sc).Where(x=>x.PrFlag==0).Select(x=>new{ID=x.PrId,商品名=x.PrName,メーカー=x.Ma.MaName,価格=x.Price,安全在庫=x.PrSafetyStock,分類=x.Sc.ScName}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Stock:ListWindow{public F_Stock():base("在庫管理"){Load();}protected override void Load(){try{Display(Db.TStocks.Include(x=>x.Pr).Where(x=>x.StFlag==0).Select(x=>new{商品=x.Pr.PrName,在庫=x.StQuantity,安全在庫=x.Pr.PrSafetyStock,発注推奨=x.StQuantity<=x.Pr.PrSafetyStock?"発注推奨":""}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Employee:ListWindow{public F_Employee():base("社員管理"){Load();}protected override void Load(){try{Display(Db.MEmployees.Include(x=>x.Po).Include(x=>x.So).Where(x=>x.EmFlag==0).Select(x=>new{社員ID=x.EmId,氏名=x.EmName,役職=x.Po.PoName,営業所=x.So.SoName,電話=x.EmPhone}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Sale:ListWindow{public F_Sale():base("売上一覧"){Load();}protected override void Load(){try{Display(Db.TSales.Include(x=>x.Cl).Include(x=>x.So).Where(x=>x.SaFlag==0).Select(x=>new{売上ID=x.SaId,顧客=x.Cl.ClName,営業所=x.So.SoName,日付=x.SaDate}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Chumon:ListWindow{public F_Chumon():base("注文管理"){Load();}protected override void Load(){try{Display(Db.TChumons.Include(x=>x.Cl).Where(x=>x.ChFlag==0).Select(x=>new{注文ID=x.ChId,顧客=x.Cl.ClName,日付=x.ChDate,確定=x.ChStateFlag==1?"確定":"未確定"}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Hattyu:ListWindow{public F_Hattyu():base("発注管理"){Load();}protected override void Load(){try{Display(Db.THattyus.Include(x=>x.Ma).Where(x=>x.HaFlag==0).Select(x=>new{発注ID=x.HaId,メーカー=x.Ma.MaName,日付=x.HaDate,入庫=x.WaWarehouseFlag==1?"済":"未入庫"}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Warehousing:ListWindow{public F_Warehousing():base("入庫管理"){Load();}protected override void Load(){try{Display(Db.TWarehousings.Where(x=>x.WaFlag==0).Select(x=>new{入庫ID=x.WaId,発注ID=x.HaId,日付=x.WaDate,棚入れ=x.WaShelfFlag==1?"済":"未"}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Syukko:ListWindow{public F_Syukko():base("出庫管理"){Load();}protected override void Load(){try{Display(Db.TSyukkos.Include(x=>x.Cl).Where(x=>x.SyFlag==0).Select(x=>new{出庫ID=x.SyId,顧客=x.Cl.ClName,日付=x.SyDate,確定=x.SyStateFlag==1?"確定":"未確定"}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Arrival:ListWindow{public F_Arrival():base("入荷管理"){Load();}protected override void Load(){try{Display(Db.TArrivals.Include(x=>x.Cl).Where(x=>x.ArFlag==0).Select(x=>new{入荷ID=x.ArId,顧客=x.Cl.ClName,日付=x.ArDate,確定=x.ArStateFlag==1?"確定":"未確定"}));}catch(Exception e){ShowError(e);}}}
public sealed class F_Shipment:ListWindow{public F_Shipment():base("出荷管理"){Load();}protected override void Load(){try{Display(Db.TShipments.Include(x=>x.Cl).Where(x=>x.ShFlag==0).Select(x=>new{出荷ID=x.ShId,顧客=x.Cl.ClName,確定=x.ShStateFlag==1?"確定":"未確定"}));}catch(Exception e){ShowError(e);}}}
public sealed class F_PasswordChange:Window{TextBox oldBox=new(),newBox=new();public F_PasswordChange(){Title="パスワード変更";Width=400;Height=260;var p=new StackPanel{Margin=new Thickness(20)};p.Children.Add(new TextBlock{Text="現在のパスワード"});p.Children.Add(oldBox);p.Children.Add(new TextBlock{Text="新しいパスワード"});p.Children.Add(newBox);var b=new Button{Content="変更",Margin=new Thickness(0,15,0,0)};b.Click+=(s,e)=>{if(BusinessService.ChangePassword(AppSession.Employee!.EmId,oldBox.Text,newBox.Text,out var m))MessageBox.Show(m);else MessageBox.Show(m,"入力エラー");};p.Children.Add(b);Content=p;}}
